def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Each diagonal pair of a color marks a line; extend the line in both
    # directions, stopping at any cell of another color.
    colors = {v for row in grid for v in row if v not in (0, 8)}
    for color in colors:
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        for i, (r, c) in enumerate(pts):
            for rr, cc in pts[i + 1:]:
                dr, dc = rr - r, cc - c
                if abs(dr) == abs(dc) and dr != 0:
                    dr //= abs(dr)
                    dc //= abs(dc)
                    for sign in (-1, 1):
                        y, x = r, c
                        while 0 <= y < h and 0 <= x < w:
                            if grid[y][x] not in (0, 8, color):
                                break
                            out[y][x] = color
                            y += sign * dr
                            x += sign * dc
    return out
